using MaintenancePRO.Services; using MaintenancePRO.Models; using System.Collections.ObjectModel; namespace MaintenancePRO.ViewModels; public sealed class HistoryViewModel:BaseViewModel { public ObservableCollection<MaintenanceRecord> Records{get;} public HistoryViewModel(DemoDataService data){Records=data.Records;} string _filter="Tous"; public string Filter{get=>_filter;set{if(Set(ref _filter,value))OnPropertyChanged(nameof(FilteredRecords));}} public IEnumerable<MaintenanceRecord> FilteredRecords=>Filter=="Tous"?Records:Records.Where(r=>r.Status==Filter); public string[] Filters {get;}={"Tous","Ouverte","En cours","Clôturée"}; }